// Program.cs (ANTES) — tudo dentro do mesmo request

app.MapPost("/api/pedidos", async (NovoPedidoRequest req, AppDb db, IGatewayPagamento gateway) =>
{
    // TRES operacoes, em serie, no MESMO request: gravar, decrementar estoque,
    // cobrar. O cliente so recebe resposta quando a ULTIMA termina — e ela e a
    // mais lenta das tres, porque depende de um servico que a Cadencia nao controla.
    var pedido = new Pedido(req.ItemId, req.Quantidade, req.ValorCentavos);
    db.Pedidos.Add(pedido);
    db.Estoque.Decrementar(req.ItemId, req.Quantidade);
    await db.SaveChangesAsync();

    // ~700 ms no p50, sem retry, sem timeout configurado. Sob carga normal
    // (0,5 pedido/s) isso e invisivel. Sob 10x, e o gargalo inteiro.
    await gateway.CobrarAsync(pedido.Id, req.ValorCentavos);

    return Results.Ok(pedido);
});

// Program.cs (DEPOIS) — a API registra a intencao e responde

app.MapPost("/api/pedidos", async (NovoPedidoRequest req, IAmazonSQS sqs, IOptions<FilaConfig> cfg) =>
{
    var pedidoId = Guid.NewGuid().ToString();

    var corpo = JsonSerializer.Serialize(new PedidoRecebido(
        PedidoId: pedidoId,
        ItemId: req.ItemId,
        Quantidade: req.Quantidade,
        ValorCentavos: req.ValorCentavos));

    // A API so registra a INTENCAO. Nenhum estoque e decrementado e nenhum
    // gateway e chamado aqui — isso passou a ser trabalho do consumidor,
    // minutos ou so segundos depois, no seu proprio ritmo.
    await sqs.SendMessageAsync(new SendMessageRequest
    {
        QueueUrl = cfg.Value.FilaPedidosUrl,
        MessageBody = corpo,
        MessageAttributes = new Dictionary<string, MessageAttributeValue>
        {
            ["PedidoId"] = new() { DataType = "String", StringValue = pedidoId },
        },
    });

    // 202: "recebi a intencao", nao "processei o pedido". E a mudanca de
    // contrato que o cliente da API precisa saber — nao e mais um 200 com o
    // pedido confirmado.
    return Results.Accepted(value: new { pedidoId, status = "recebido" });
});

# consumidor.tf — o Lambda, o event source mapping e as permissoes minimas

resource "aws_lambda_function" "consumidor" {
  function_name = "${var.projeto}-consumidor-pedidos"
  runtime       = "dotnet8"
  handler       = "Consumidor::Cadencia.Pedidos.Consumidor.Function::FunctionHandler"
  role          = aws_iam_role.consumidor.arn

  # RELOGIO 2: o timeout da funcao. O visibility_timeout de 60 s da fila (em
  # fila.tf) tem de ser pelo menos 6x este valor — e 6 x 10 = 60, sem folga
  # sobrando. Subir este numero sem revisar o outro quebra a relacao.
  timeout     = 10
  memory_size = 512

  filename         = data.archive_file.consumidor.output_path
  source_code_hash = data.archive_file.consumidor.output_base64sha256

  environment {
    variables = {
      TABELA_IDEMPOTENCIA = aws_dynamodb_table.pedidos_processados.name
    }
  }
}

resource "aws_lambda_event_source_mapping" "consumidor_pedidos" {
  event_source_arn = aws_sqs_queue.pedidos.arn
  function_name    = aws_lambda_function.consumidor.arn

  batch_size = 10 # o padrao; e tambem o teto de uma fila FIFO. Standard aceita ate 10.000.

  # O MECANISMO central deste laboratorio, do lado da configuracao. Sem isto,
  # UMA mensagem com erro num lote de 10 devolve as OUTRAS NOVE para a fila
  # tambem — inclusive as que ja tiveram efeito aplicado. Com isto, a funcao
  # devolve so os IDs que de fato falharam.
  function_response_types = ["ReportBatchItemFailures"]

  maximum_batching_window_in_seconds = 5
}

data "aws_iam_policy_document" "consumidor_permissoes" {
  statement {
    effect  = "Allow"
    actions = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"]
    # So a fila PRINCIPAL. O consumidor nunca le da DLQ — quem le a DLQ e um
    # humano investigando, nao o codigo de producao.
    resources = [aws_sqs_queue.pedidos.arn]
  }

  statement {
    effect    = "Allow"
    actions   = ["dynamodb:PutItem"]
    resources = [aws_dynamodb_table.pedidos_processados.arn]
  }
}

resource "aws_iam_role" "consumidor" {
  name               = "${var.projeto}-consumidor-pedidos"
  assume_role_policy = data.aws_iam_policy_document.consumidor_assume.json
}

resource "aws_iam_role_policy" "consumidor_permissoes" {
  role   = aws_iam_role.consumidor.id
  policy = data.aws_iam_policy_document.consumidor_permissoes.json
}

resource "aws_iam_role_policy_attachment" "consumidor_logs" {
  role       = aws_iam_role.consumidor.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# idempotencia.tf — a tabela onde a duplicata vira nao-operacao

resource "aws_dynamodb_table" "pedidos_processados" {
  name         = "${var.projeto}-pedidos-processados"
  billing_mode = "PAY_PER_REQUEST" # o trafego e o mesmo pico irregular da fila; provisionado sobraria ocioso
  hash_key     = "PedidoId"

  attribute {
    name = "PedidoId"
    type = "S"
  }

  # A marca de idempotencia nao precisa viver para sempre. 30 dias cobre
  # qualquer reentrega tardia plausivel — a retencao MAXIMA da propria fila e
  # 14 dias — sem acumular item indefinidamente.
  ttl {
    attribute_name = "ExpiraEm"
    enabled        = true
  }

  point_in_time_recovery {
    enabled = true # e o registro de "isto ja foi cobrado"; restaurar errado cobra duas vezes
  }
}

// Function.cs — consome em lote, decide por mensagem, devolve so quem falhou

using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;
using Amazon.Lambda.Core;
using Amazon.Lambda.SQSEvents;
using System.Text.Json;

[assembly: LambdaSerializer(typeof(Amazon.Lambda.Serialization.SystemTextJson.DefaultLambdaJsonSerializer))]
namespace Cadencia.Pedidos.Consumidor;

public class Function
{
    private static readonly AmazonDynamoDBClient _dynamo = new();
    private static readonly HttpClient _gatewayPagamento = new() { Timeout = TimeSpan.FromSeconds(5) };
    private static readonly string _tabela = Environment.GetEnvironmentVariable("TABELA_IDEMPOTENCIA")!;

    public async Task<SQSBatchResponse> FunctionHandler(SQSEvent evento, ILambdaContext contexto)
    {
        var falhas = new List<SQSBatchResponse.BatchItemFailure>();

        // Cada mensagem do lote e tratada de forma INDEPENDENTE: uma excecao
        // aqui nao pode impedir que as outras sejam reportadas como sucesso —
        // e para isso que existe o ReportBatchItemFailures no event source
        // mapping. Sem essa configuracao (e sem este try/catch por mensagem),
        // uma unica falha devolveria o LOTE INTEIRO para a fila.
        foreach (var mensagem in evento.Records)
        {
            try
            {
                await ProcessarPedidoAsync(mensagem, contexto);
            }
            catch (Exception ex)
            {
                contexto.Logger.LogError($"Falha ao processar {mensagem.MessageId}: {ex.Message}");
                falhas.Add(new SQSBatchResponse.BatchItemFailure { ItemIdentifier = mensagem.MessageId });
            }
        }

        return new SQSBatchResponse(falhas);
    }

    private async Task ProcessarPedidoAsync(SQSEvent.SQSMessage mensagem, ILambdaContext contexto)
    {
        var pedido = JsonSerializer.Deserialize<PedidoRecebido>(mensagem.Body)!;

        // O MECANISMO de idempotencia mora INTEIRO nesta escrita condicional.
        // attribute_not_exists(PedidoId) so deixa o PutItem ter sucesso se
        // este for o PRIMEIRO PutItem com essa chave. SQS pode entregar a
        // mesma mensagem mais de uma vez (at-least-once, nunca exactly-once
        // numa fila standard); esta condicao e o que garante que o EFEITO de
        // negocio acontece uma vez so, nao a fila.
        try
        {
            await _dynamo.PutItemAsync(new PutItemRequest
            {
                TableName = _tabela,
                Item = new Dictionary<string, AttributeValue>
                {
                    ["PedidoId"] = new AttributeValue { S = pedido.PedidoId },
                    ["ProcessadoEm"] = new AttributeValue { S = DateTimeOffset.UtcNow.ToString("O") },
                    // TTL: a marca de idempotencia nao precisa viver para sempre.
                    ["ExpiraEm"] = new AttributeValue
                        { N = DateTimeOffset.UtcNow.AddDays(30).ToUnixTimeSeconds().ToString() },
                },
                ConditionExpression = "attribute_not_exists(PedidoId)",
            });
        }
        catch (ConditionalCheckFailedException)
        {
            // Chegou aqui de novo. NAO e um erro de aplicacao: e o contrato
            // at-least-once se manifestando. O efeito de negocio ja aconteceu
            // na entrega anterior — pular e devolver sucesso e a resposta
            // CORRETA, e e exatamente o que evita a cobranca duplicada.
            contexto.Logger.LogInformation(
                $"Pedido {pedido.PedidoId} ja processado — reentrega ignorada, sem duplicar efeito");
            return;
        }

        // So chega aqui quando o PutItem acima criou o item pela PRIMEIRA vez.
        // E aqui, e so aqui, que o efeito de negocio acontece.
        await DebitarEstoqueAsync(pedido);
        await CobrarCartaoAsync(pedido);
    }

    private static async Task DebitarEstoqueAsync(PedidoRecebido pedido)
    {
        // Decremento no PostgreSQL do L01/L03 — fora do escopo deste trecho.
        // O ponto deste laboratorio nao e ONDE o estoque mora, e sim QUANDO o
        // decremento acontece: depois da condicao de escrita ter passado.
        await Task.CompletedTask;
    }

    private static async Task CobrarCartaoAsync(PedidoRecebido pedido)
    {
        var resposta = await _gatewayPagamento.PostAsJsonAsync(
            "https://gateway.exemplo/cobrancas",
            new { pedido.PedidoId, pedido.ValorCentavos });
        resposta.EnsureSuccessStatusCode(); // erro aqui vira excecao e o item entra em batchItemFailures
    }
}

public record PedidoRecebido(string PedidoId, string ItemId, int Quantidade, int ValorCentavos);
